package com.lk.esp; import android.app.*; import android.content.Intent; import android.graphics.*; import android.os.*; import android.view.*; public class OverlayService extends Service { @Override public IBinder onBind(Intent i) { return null; } @Override public int onStartCommand(Intent i, int f, int id) { NotificationChannel ch = new NotificationChannel("o", "Ovl", NotificationManager.IMPORTANCE_LOW); getSystemService(NotificationManager.class).createNotificationChannel(ch); startForeground(2, new Notification.Builder(this, "o").setSmallIcon(android.R.drawable.ic_menu_view).build()); WindowManager wm = (WindowManager) getSystemService(WINDOW_SERVICE); View v = new View(this) { @Override protected void onDraw(Canvas c) { super.onDraw(c); Paint p = new Paint(); p.setColor(Color.RED); p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(5); c.drawRect(200, 200, 400, 600, p); invalidate(); } }; wm.addView(v, new WindowManager.LayoutParams(-1, -1, WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY, WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE | WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE, PixelFormat.TRANSLUCENT)); return START_STICKY; } }
